<?php

declare(strict_types=1);

/*
 * Code style: Symfony's coding standard, plus this project's conventions.
 * make cs checks it (also in CI); make cs-fix applies it.
 */

use PhpCsFixer\Config;
use PhpCsFixer\Finder;

$finder = new Finder()
    ->in(__DIR__)
    ->exclude([
        'var',
        'migrations',   // generated by Doctrine; history, not hand-written code
    ])
    ->notPath([
        'config/bundles.php',
        'config/reference.php',
    ]);

return new Config()
    ->setRiskyAllowed(true)   // only for declare_strict_types below
    ->setRules([
        '@Symfony' => true,
        'declare_strict_types' => true,
        // Import global classes, functions and constants (use, use function,
        // use const) instead of writing \DateTimeImmutable or \sprintf.
        'global_namespace_import' => [
            'import_classes' => true,
            'import_functions' => true,
            'import_constants' => true,
        ],
        'native_function_invocation' => false,
        'native_constant_invocation' => false,
        // Keep @throws tags in alphabetical order.
        'phpdoc_order_by_value' => ['annotations' => ['throws']],
        // Visibility is required on methods and constants, not properties:
        // asymmetric properties are written private(set), without public.
        'modifier_keywords' => ['elements' => ['method', 'const']],
        // Docblock summaries are often routes or signatures; no forced period.
        'phpdoc_summary' => false,
    ])
    ->setFinder($finder);
